import{_ as l,c as r,o as i,ah as e}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"易経の歴史","description":"易経の歴史，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"易経の歴史","description":"易経の歴史，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"ja/articles/history/index.md","filePath":"ja/articles/history/index.md"}'),n={name:"ja/articles/history/index.md"};function t(o,a,s,h,d,c){return i(),r("div",null,[...a[0]||(a[0]=[e('<h1 id="『易経』探究-八卦の成立と中華文明の精神的座標" tabindex="-1">『易経』探究：八卦の成立と中華文明の精神的座標 <a class="header-anchor" href="#『易経』探究-八卦の成立と中華文明の精神的座標" aria-label="Permalink to “『易経』探究：八卦の成立と中華文明の精神的座標”">​</a></h1><p>中国古典の中で『周易』（易経）は、特別な中心的地位を占めてきました。数千年にわたる思想的深みと文化的広がりにより「群経の首」「大道の源」と称されます。これは特定の一人の著作ではなく、古代の先民から先秦の学者たちまでが積み重ねた知の結晶であり、自然観察から哲学体系へと成熟していく過程そのものが、初期中国文明の凝縮でもあります。</p><h3 id="_1-八卦の源流-宇宙秩序の原初的な解読" tabindex="-1">1. 八卦の源流：宇宙秩序の原初的な解読 <a class="header-anchor" href="#_1-八卦の源流-宇宙秩序の原初的な解読" aria-label="Permalink to “1. 八卦の源流：宇宙秩序の原初的な解読”">​</a></h3><p>八卦は『易経』の記号的基盤で、その淵源は紀元前 3000 年頃の新石器時代後期に遡るとされます。伝説では伏羲が「観象授時」――天を仰いで日月星辰の運行を観察し、地を俯して山川草木の変化を読み取り、四季の循環と昼夜の交替から宇宙を支配する八つの基本的な力を抽出したと伝えられます。</p><p>伏羲は「—」（陽爻：剛健・能動）と「--」（陰爻：柔順・受動）を用い、乾（天）・坤（地）・震（雷）・巽（風）・坎（水）・離（火）・艮（山）・兌（沢）の八卦を構成しました。極めて簡素な線記号で自然現象をまとめると同時に、「天人合一」という原初的な世界観――天地の変化は八卦の組合せと推演で把握できる――を含意しています。</p><h3 id="_2-伝承-三代易書から哲学古典へ" tabindex="-1">2. 伝承：三代易書から哲学古典へ <a class="header-anchor" href="#_2-伝承-三代易書から哲学古典へ" aria-label="Permalink to “2. 伝承：三代易書から哲学古典へ”">​</a></h3><p>八卦の体系は固定されたものではなく、夏・商・周の変遷の中で拡張され、より具体的な占筮と解釈の枠組みへと発展しました。</p><ul><li><strong>夏代・『連山』</strong>：艮（山）を首とし、山地に根ざす生活・農耕・祭祀に結びついた経験が色濃いとされます。</li><li><strong>商代・『帰蔵』</strong>：坤（地）を首とし、耕作と祖先祭祀、吉凶判断を重視し、甲骨占い文化とも響き合います。</li><li><strong>周代・『周易』の成熟</strong>：周文王が八卦を重ねて六十四卦を整え、卦辞を付し、周公が彖伝・象伝などで卦理を解釈し、礼楽・倫理と結びつけたとされます。</li></ul><p>春秋末期には「十翼」（文言・繋辞・説卦など）が整い、占筮書としての側面を超えて、陰陽・剛柔の理を語る哲学古典へと昇華しました。</p><h3 id="_3-文化的影響-千年を貫く広がり" tabindex="-1">3. 文化的影響：千年を貫く広がり <a class="header-anchor" href="#_3-文化的影響-千年を貫く広がり" aria-label="Permalink to “3. 文化的影響：千年を貫く広がり”">​</a></h3><p>『易経』の影響は書物の内部に留まらず、中国文明の多方面へ浸透し、思考の基層を形づくりました。</p><ul><li><strong>思想</strong>：陰陽相生・天人合一は、儒家の倫理秩序や道家の宇宙観の枠組みに影響。</li><li><strong>文学・芸術</strong>：卦象や卦辞のイメージが詩・書画の題材となり、虚実のバランス美学へ。</li><li><strong>政治・社会</strong>：「窮すれば変じ、変ずれば通ず」という発想が改革の理論背景になり、乾「自強不息」・坤「厚徳載物」は士人の理想像に。</li><li><strong>科学的領域</strong>：医学の陰陽五行、天文暦法や推算法などにも、弁証的思考の影響が見られます。</li></ul><p>今日でも『易経』の弁証的な視点は、自己理解や意思決定の「考え方」として参照され続けています。</p><hr><h1 id="易経の学術的伝承-主要な流派と代表的人物" tabindex="-1">易経の学術的伝承：主要な流派と代表的人物 <a class="header-anchor" href="#易経の学術的伝承-主要な流派と代表的人物" aria-label="Permalink to “易経の学術的伝承：主要な流派と代表的人物”">​</a></h1><p>『周易』の経伝が整って以降、解釈の営みは途切れることなく続きました。時代の思想潮流や方法論の違いにより、易学はさまざまな流派へ分化し、互いに対立しつつも融合しながら発展していきます。ここでは、古代〜宋明にかけて大きな枠組みとなった三系統（象数・義理・図書）を概観します。</p><h3 id="_1-象数派-記号-象-と数-数理-による推演-漢〜唐" tabindex="-1">1. 象数派：記号（象）と数（数理）による推演（漢〜唐） <a class="header-anchor" href="#_1-象数派-記号-象-と数-数理-による推演-漢〜唐" aria-label="Permalink to “1. 象数派：記号（象）と数（数理）による推演（漢〜唐）”">​</a></h3><p>卦象・爻象、陰陽数・天地数を中心に据え、天文暦法や占筮との結びつきを重視する流れです。漢代には「天人感応」の思想とも響き合い、実用的体系が整えられました。</p><h4 id="京房-西漢-—-納甲・飛伏" tabindex="-1">京房（西漢）— 納甲・飛伏 <a class="header-anchor" href="#京房-西漢-—-納甲・飛伏" aria-label="Permalink to “京房（西漢）— 納甲・飛伏”">​</a></h4><ul><li><strong>要点</strong>：十干十二支を六爻に配当する「納甲」、顕在／潜在の爻を読む「飛伏」などで占断体系を精緻化。</li><li><strong>影響</strong>：後世の六爻占（納甲）や術数全般に大きな影響。</li></ul><h4 id="鄭玄-後漢-—-爻辰-天文対応" tabindex="-1">鄭玄（後漢）— 爻辰（天文対応） <a class="header-anchor" href="#鄭玄-後漢-—-爻辰-天文対応" aria-label="Permalink to “鄭玄（後漢）— 爻辰（天文対応）”">​</a></h4><ul><li><strong>要点</strong>：卦爻を時辰・星宿などと対応づけ、天文的観点から注釈を試みる。今古文の折衷も特徴。</li><li><strong>影響</strong>：学術的注釈として権威を持ち、後代の読解基盤に。</li></ul><h4 id="孔穎達-唐-—-官修『周易正義』" tabindex="-1">孔穎達（唐）— 官修『周易正義』 <a class="header-anchor" href="#孔穎達-唐-—-官修『周易正義』" aria-label="Permalink to “孔穎達（唐）— 官修『周易正義』”">​</a></h4><ul><li><strong>要点</strong>：漢代の象数と魏晋の義理を調停し、「象は義の本」として両面から解釈を整理。</li><li><strong>影響</strong>：科挙の標準教材となり、後世への公的伝承を確立。</li></ul><h3 id="_2-義理派-哲学・倫理として読む-魏晋〜宋明" tabindex="-1">2. 義理派：哲学・倫理として読む（魏晋〜宋明） <a class="header-anchor" href="#_2-義理派-哲学・倫理として読む-魏晋〜宋明" aria-label="Permalink to “2. 義理派：哲学・倫理として読む（魏晋〜宋明）”">​</a></h3><p>漢代の過度な附会を批判し、卦象を手がかりにしつつも、最終的には義理（道徳・宇宙論）を掴むことを重視する流れです。宋明の理学・心学と結びつき、思想史の中核を占めました。</p><h4 id="王弼-三国魏-—-得意忘象" tabindex="-1">王弼（三国魏）— 得意忘象 <a class="header-anchor" href="#王弼-三国魏-—-得意忘象" aria-label="Permalink to “王弼（三国魏）— 得意忘象”">​</a></h4><ul><li><strong>要点</strong>：「象は意を示す器であり、言は象を述べる器」とし、象数に拘泥せず義理へ到達する方法を提示。</li><li><strong>影響</strong>：以後の易学解釈の方向性を大きく転換し、義理中心の読解を主流化。</li></ul><h4 id="程頤-北宋-—-以儒釈易" tabindex="-1">程頤（北宋）— 以儒釈易 <a class="header-anchor" href="#程頤-北宋-—-以儒釈易" aria-label="Permalink to “程頤（北宋）— 以儒釈易”">​</a></h4><ul><li><strong>要点</strong>：易を儒家倫理の根拠として読み、「天道＝人道」の指針として吉凶悔吝を捉える。</li><li><strong>影響</strong>：理学の哲学基盤として易を位置づけ、後代の儒学に深く浸透。</li></ul><h4 id="朱熹-南宋-—-象義の調和" tabindex="-1">朱熹（南宋）— 象義の調和 <a class="header-anchor" href="#朱熹-南宋-—-象義の調和" aria-label="Permalink to “朱熹（南宋）— 象義の調和”">​</a></h4><ul><li><strong>要点</strong>：象数を土台として認めつつ、義理へ統合する。経（卦爻辞）→伝（十翼）の順で読む姿勢を強調。</li><li><strong>影響</strong>：明清の標準注となり、近世の易学理解を規定。</li></ul><h4 id="王陽明-明-—-心即易理" tabindex="-1">王陽明（明）— 心即易理 <a class="header-anchor" href="#王陽明-明-—-心即易理" aria-label="Permalink to “王陽明（明）— 心即易理”">​</a></h4><ul><li><strong>要点</strong>：易理は外にあるのではなく「本心」に体現されるとして、事上での実践を重視。</li><li><strong>影響</strong>：義理派に主体性を与え、心学的読解の道を開く。</li></ul><h3 id="_3-図書派-河図・洛書と図式による宇宙論-宋〜元" tabindex="-1">3. 図書派：河図・洛書と図式による宇宙論（宋〜元） <a class="header-anchor" href="#_3-図書派-河図・洛書と図式による宇宙論-宋〜元" aria-label="Permalink to “3. 図書派：河図・洛書と図式による宇宙論（宋〜元）”">​</a></h3><p>河図・洛書などの「図」に易の源流を求め、先天／後天の配列や時間循環を図式で説明しようとする流れです。</p><h4 id="邵雍-北宋-—-先天八卦図" tabindex="-1">邵雍（北宋）— 先天八卦図 <a class="header-anchor" href="#邵雍-北宋-—-先天八卦図" aria-label="Permalink to “邵雍（北宋）— 先天八卦図”">​</a></h4><ul><li><strong>要点</strong>：先天八卦と後天八卦を区別し、宇宙の本然／人事の運行を図として表す。『皇極経世』で時間単位（元会運世）と結びつけた宇宙論を構築。</li><li><strong>影響</strong>：易学・術数の重要な図式として後代に継承され、思考の枠組みを提供。</li></ul><h3 id="まとめ-多様性こそ易学の生命力" tabindex="-1">まとめ：多様性こそ易学の生命力 <a class="header-anchor" href="#まとめ-多様性こそ易学の生命力" aria-label="Permalink to “まとめ：多様性こそ易学の生命力”">​</a></h3><p>象数派は天道の規律を、義理派は人道の倫理を、図書派は宇宙生成の図式を、それぞれ重視しました。流派は分かれても、問いは一つ――「易とは何か」。対立と融合を通じて、易は占筮の記号体系から、哲学・倫理・文化を貫く中核典籍へと成熟していったのです。</p><hr><h1 id="易経の占筮の流れ-主要な方法と時代背景" tabindex="-1">易経の占筮の流れ：主要な方法と時代背景 <a class="header-anchor" href="#易経の占筮の流れ-主要な方法と時代背景" aria-label="Permalink to “易経の占筮の流れ：主要な方法と時代背景”">​</a></h1><p>易経の占筮は、典籍と同じく古い伝統を持ちます。先秦の筮竹による厳粛な儀式から、唐宋以降の銭（コイン）による簡便な方法、さらに物象・時間を用いる体系へと、社会の要請に合わせて変化してきました。ここでは代表的な方法を、成立と流行の文脈とともに整理します。</p><h3 id="_1-大衍筮法-先秦〜漢代の「正統」筮占" tabindex="-1">1. 大衍筮法：先秦〜漢代の「正統」筮占 <a class="header-anchor" href="#_1-大衍筮法-先秦〜漢代の「正統」筮占" aria-label="Permalink to “1. 大衍筮法：先秦〜漢代の「正統」筮占”">​</a></h3><p>『易伝・繋辞上』に記される、体系的な最古級の占筮法です。50 本の筮竹から 1 本を除いて太極を象徴し、残り 49 本で「分二・掛一・揲四・帰奇」を繰り返して一爻を得ます（六爻で一卦）。</p><p><strong>基本の流れ（概要）</strong></p><ol><li>分二：49 本を二つに分ける（天地）。</li><li>掛一：右の束から 1 本を取る（人）。</li><li>揲四：左右を 4 本ずつ数える（四時）。</li><li>帰奇：余りをまとめる（一次の変）。</li></ol><p>操作が複雑で時間を要するため、後世には簡略法へと移っていきますが、易学上は「占筮の本」として重視されます。</p><h3 id="_2-略筮法-筮竹法の簡略化-過渡形態" tabindex="-1">2. 略筮法：筮竹法の簡略化（過渡形態） <a class="header-anchor" href="#_2-略筮法-筮竹法の簡略化-過渡形態" aria-label="Permalink to “2. 略筮法：筮竹法の簡略化（過渡形態）”">​</a></h3><p>大衍筮法の「耗時・労力」を軽減するために簡略化された形です。筮竹の本数を減らす、手順を統合するなど、いくつかの系統があったと考えられます。後の簡便な占法への橋渡しとして位置づけられます。</p><h3 id="_3-銭-コイン-占-民間の主流-南北朝〜現代" tabindex="-1">3. 銭（コイン）占：民間の主流（南北朝〜現代） <a class="header-anchor" href="#_3-銭-コイン-占-民間の主流-南北朝〜現代" aria-label="Permalink to “3. 銭（コイン）占：民間の主流（南北朝〜現代）”">​</a></h3><p>筮竹の演算を、三枚の銭の投擲で代替する方法です。隋唐以降に民間で普及し、現在も最も一般的な形式の一つです。</p><p><strong>三枚銭の基本対応（よくある方式）</strong></p><ul><li>両背一字：少陽（—）</li><li>両字一背：少陰（--）</li><li>三背：老陽（—○）※動爻</li><li>三字：老陰（--×）※動爻</li></ul><p>得られた本卦・之卦と動爻（爻辞）を軸に解釈します（納甲などの理論と組み合わせる流派もあります）。</p><h3 id="_4-梅花易数-物象起卦-宋代〜現代" tabindex="-1">4. 梅花易数：物象起卦（宋代〜現代） <a class="header-anchor" href="#_4-梅花易数-物象起卦-宋代〜現代" aria-label="Permalink to “4. 梅花易数：物象起卦（宋代〜現代）”">​</a></h3><p>筮竹や銭に依らず、時間・見聞した物象・文字などから起卦する体系です。「先天八卦数」（乾1・兌2・離3・震4・巽5・坎6・艮7・坤8）を用い、上卦／下卦／動爻を導きます。体（主題）と用（影響）を五行の生克関係で読むのが基本です。</p><h3 id="_5-変遷に見える三つの傾向" tabindex="-1">5. 変遷に見える三つの傾向 <a class="header-anchor" href="#_5-変遷に見える三つの傾向" aria-label="Permalink to “5. 変遷に見える三つの傾向”">​</a></h3><ol><li><strong>媒体の簡素化</strong>：筮竹 → 銭 → 物象へ（儀式から日常ツールへ）。</li><li><strong>理論の融合</strong>：納甲・五行・先天図など、時代ごとに体系が交差。</li><li><strong>主体性の強調</strong>：外的な「神意」から、問いと解釈の技法へ。</li></ol><p>形式は違っても、根底にあるのは「変化を観て、兆し（機）を知る」という易の知恵です。</p><hr><h1 id="易の核心思想" tabindex="-1">易の核心思想 <a class="header-anchor" href="#易の核心思想" aria-label="Permalink to “易の核心思想”">​</a></h1><ul><li><strong>変易</strong>：万物は移ろい変化する。</li><li><strong>不易</strong>：変化の背後に、貫く法則がある。</li><li><strong>簡易</strong>：要点をつかみ、簡によって繁を御する。</li></ul><p>中正・時中・陰陽のバランスを重んじ、流れに沿って行動します。天人合一とは、自然を観察し身心を整え、調和ある選択へつなげる態度です。</p>',64)])])}const b=l(n,[["render",t]]);export{p as __pageData,b as default};
